def preserve(path,target):
 raw=path.read_bytes();target.parent.mkdir(parents=True,exist_ok=True)
 compressed=len(raw)>50000 and path.suffix!='.gz'
 if compressed:target=target.with_name(target.name+'.gz');target.write_bytes(gzip.compress(raw,mtime=0))
 else:target.write_bytes(raw)
 saved=target.read_bytes();assert (gzip.decompress(saved) if compressed else saved)==raw
 manifest.append({'path':str(target.relative_to(root)),'original_file':str(path),'bytes':len(saved),'sha256':hashlib.sha256(saved).hexdigest(),'encoding':'gzip' if compressed else 'identity','decoded_bytes':len(raw),'decoded_sha256':hashlib.sha256(raw).hexdigest()})
